def minPath(grid, k):
    n = len(grid)
    # Locate the cell containing 1; the lexicographically smallest path starts there.
    r, c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j

    result = [grid[r][c]]
    for _ in range(k - 1):
        best = None
        best_pos = None
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if best is None or grid[nr][nc] < best:
                    best = grid[nr][nc]
                    best_pos = (nr, nc)
        r, c = best_pos
        result.append(best)
    return result
```

