def minPath(grid, k):
    n = len(grid)

    # Locate the cell containing 1; the lexicographically smallest path must start there.
    start = None
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start = (r, c)
                break
        if start is not None:
            break

    path = [1]
    r, c = start
    for _ in range(k - 1):
        best = None
        best_pos = None
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if best is None or grid[nr][nc] < best:
                    best = grid[nr][nc]
                    best_pos = (nr, nc)
        path.append(best)
        r, c = best_pos

    return path
